program='''def transform(grid):
    h, n = len(grid), len(grid[0])
    frame = grid[0][0]
    width = 0
    while width < n and grid[0][width] == frame:
        width += 1

    # Build normalized masks for the colored shapes on the right.
    by_color = {}
    for r in range(h):
        for c in range(width, n):
            color = grid[r][c]
            if color != 0:
                by_color.setdefault(color, []).append((r, c))
    objects = {}
    for color, cells in by_color.items():
        min_r = min(r for r, _ in cells)
        max_r = max(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        max_c = max(c for _, c in cells)
        objects[color] = (max_r - min_r + 1, max_c - min_c + 1,
                          frozenset((r - min_r, c - min_c) for r, c in cells))

    boundaries = [r for r in range(h) if all(grid[r][c] == frame for c in range(width))]
    out = [row[:width] for row in grid]
    for top, bottom in zip(boundaries, boundaries[1:]):
        cells = [(r - top - 1, c - 1)
                 for r in range(top + 1, bottom)
                 for c in range(1, width - 1)
                 if grid[r][c] == 0]
        if not cells:
            continue
        min_r = min(r for r, _ in cells)
        max_r = max(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        max_c = max(c for _, c in cells)
        mask = frozenset((r - min_r, c - min_c) for r, c in cells)
        key = (max_r - min_r + 1, max_c - min_c + 1, mask)
        color = next((color for color, obj in objects.items() if obj == key), None)
        if color is not None:
            for r in range(top + 1, bottom):
                for c in range(1, width - 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out
'''
